"use strict";
/* Comprehensive source-linked anatomy cloze pack: every authored section is represented, with region floors of max(8, twice the section count) and 12 for operative regions. Generated as literal objects; existing IDs and cards are untouched. */
window.ANATOMY.cards.push(
  {"id":"acomp-cham-pericardium-s01-01","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Layers","text":"{{c1::Fibrous pericardium}}: tough outer layer, fused to the central tendon of the diaphragm inferiorly and the great vessels superiorly."},
  {"id":"acomp-cham-pericardium-s01-02","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Layers","text":"{{c1::Serous pericardium}}: has a parietal layer (adherent to the fibrous pericardium) and a visceral layer (adherent to the epicardium)."},
  {"id":"acomp-cham-pericardium-s01-03","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Layers","text":"The potential space between them is the {{c1::pericardial cavity}}, normally containing 5–10 mL of clear fluid secreted by mesothelial cells."},
  {"id":"acomp-cham-pericardium-s02-01","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Pericardial Sinuses","text":"{{c1::Transverse sinus}}: lies behind the aorta and pulmonary trunk, in front of the SVC and left atrial appendage."},
  {"id":"acomp-cham-pericardium-s02-02","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Pericardial Sinuses","text":"{{c1::Oblique sinus}}: lies posterior to the left atrium, between the four pulmonary veins medially and the IVC."},
  {"id":"acomp-cham-pericardium-s02-03","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Pericardial Sinuses","text":"Used to pass a clamp around {{c1::both great arteries}} together (relevant during cross-clamping)."},
  {"id":"acomp-cham-pericardium-s03-01","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Pericardial reflections define the transverse and {{c1::oblique sinuses}} used for clamping, cannulation, and posterior atrial exposure."},
  {"id":"acomp-cham-pericardium-s03-02","region":"cham-pericardium","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"During reoperation these spaces may be obliterated by {{c1::adhesions}}, so the normal map remains the reference even when the plane is no longer visible."},
  {"id":"acomp-cham-atria-s01-01","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Right Atrium","text":"Key landmarks include the {{c1::crista terminalis}} (a muscular ridge separating the smooth posterior wall from the trabeculated anterior wall), the terminal groove (sulcus terminalis) externally, and the right atrial appendage."},
  {"id":"acomp-cham-atria-s01-02","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Right Atrium","text":"The {{c1::right atrium}} receives blood from the SVC superiorly, the IVC inferiorly, and the coronary sinus posteriorly."},
  {"id":"acomp-cham-atria-s02-01","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Interatrial Septum and Fossa Ovalis","text":"The interatrial septum features the {{c1::fossa ovalis}} — the adult remnant of the foramen ovale, representing the site of the ostium secundum."},
  {"id":"acomp-cham-atria-s02-02","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Interatrial Septum and Fossa Ovalis","text":"A {{c1::patent foramen ovale (PFO)}} persists in ~25% of the population."},
  {"id":"acomp-cham-atria-s03-01","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Left Atrium","text":"The {{c1::left atrium}} is the most posterior cardiac chamber."},
  {"id":"acomp-cham-atria-s03-02","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Left Atrium","text":"It receives the {{c1::four pulmonary veins}} (two on each side) and leads to the mitral valve via the mitral annulus."},
  {"id":"acomp-cham-atria-s04-01","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"{{c1::Right-atrial anatomy}} determines cannulation, atriotomy and septal exposure."},
  {"id":"acomp-cham-atria-s04-02","region":"cham-atria","category":"chambers","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"On the left, the {{c1::posterior position and proximity of the oesophagus}} explain why mitral exposure, ablation and transoesophageal imaging all share the same hazards."},
  {"id":"acomp-cham-ventricles-s01-01","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Left Ventricle","text":"The {{c1::LV}} is ellipsoidal with thick muscular walls (8–12 mm)."},
  {"id":"acomp-cham-ventricles-s01-02","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Left Ventricle","text":"It has an {{c1::inflow tract}} (mitral valve to apex) and an outflow tract (LVOT, below the aortic valve)."},
  {"id":"acomp-cham-ventricles-s02-01","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Right Ventricle","text":"The {{c1::moderator band (septomarginal trabeculation)}} crosses the RV cavity carrying the right bundle branch to the anterior papillary muscle."},
  {"id":"acomp-cham-ventricles-s02-02","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Right Ventricle","text":"The {{c1::RV}} is crescentic in cross-section, wrapping around the LV."},
  {"id":"acomp-cham-ventricles-s03-01","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Ventricular Septum","text":"{{c1::Muscular septum}}: large, formed from the ventricular myocardium of both ventricles during embryogenesis."},
  {"id":"acomp-cham-ventricles-s03-02","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Ventricular Septum","text":"{{c1::Membranous septum}}: small, thin, superior portion; formed from the fusion of endocardial cushions and descending truncal cushions."},
  {"id":"acomp-cham-ventricles-s04-01","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"The thin, {{c1::anterior RV}} is vulnerable during re-entry and cannulation; the thick LV tolerates pressure but not a poorly placed vent."},
  {"id":"acomp-cham-ventricles-s04-02","region":"cham-ventricles","category":"chambers","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"{{c1::Septal incision}} or suturing must be planned around the His-Purkinje system and coronary septal supply."},
  {"id":"acomp-cham-embryology-s01-01","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Heart Tube Formation","text":"The heart tube forms from fusion of the two {{c1::ventral aortae}}, originating from the mesodermal layer of the yolk sac."},
  {"id":"acomp-cham-embryology-s01-02","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Heart Tube Formation","text":"After longitudinal growth and rotation, it divides into three regions: the {{c1::conus truncus}} (gives rise to the aorta and pulmonary artery), the bulbus cordis, and the sinus venosus."},
  {"id":"acomp-cham-embryology-s01-03","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Heart Tube Formation","text":"After heart-tube growth and rotation, one of its three named regions is the {{c1::bulbus cordis}}."},
  {"id":"acomp-cham-embryology-s02-01","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Septation","text":"{{c1::Endocardial cushions}} partition the atrioventricular canal, forming the mitral and tricuspid valves."},
  {"id":"acomp-cham-embryology-s02-02","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Septation","text":"The {{c1::atrial septum}} forms from the septum primum and septum secundum, leaving a small opening — the foramen ovale — which normally closes after birth."},
  {"id":"acomp-cham-embryology-s02-03","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Septation","text":"The {{c1::muscular ventricular septum}} forms from ventricular myocardium; the membranous septum from endocardial cushions and descending truncal cushions."},
  {"id":"acomp-cham-embryology-s03-01","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Embryology becomes operative anatomy when a defect shifts the {{c1::conduction axis}}, valve attachments, or great-artery relationship."},
  {"id":"acomp-cham-embryology-s03-02","region":"cham-embryology","category":"chambers","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Name the {{c1::developmental lesion}}, then redraw the structures the surgeon will actually encounter."},
  {"id":"acomp-cond-sanode-s01-01","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Location and Structure","text":"The SA node is an {{c1::elliptical or horseshoe-shaped}}, sub-epicardial structure lying just lateral to the SVC-RA junction at the roof of the right atrium, at the superior end of the terminal groove (sulcus terminalis)."},
  {"id":"acomp-cond-sanode-s01-02","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Location and Structure","text":"It is {{c1::sub-epicardial}}, not deeply embedded in the myocardium."},
  {"id":"acomp-cond-sanode-s02-01","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Blood Supply","text":"The {{c1::SA nodal artery}} originates from the RCA in 55% of patients and from the circumflex artery in 45%."},
  {"id":"acomp-cond-sanode-s02-02","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Blood Supply","text":"The nodal artery passes {{c1::anterior to the SVC-RA junction in 60%}}, posterior in 33%, and around it (encircling) in 7% of patients."},
  {"id":"acomp-cond-sanode-s03-01","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Impulse Propagation","text":"From the SA node, the impulse spreads through three {{c1::internodal tracts}} (anterior, middle, and posterior) in the right atrium and via Bachmann's bundle (the interatrial pathway) to the left atrium, before reaching the AV node."},
  {"id":"acomp-cond-sanode-s03-02","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Impulse Propagation","text":"The interatrial pathway carrying the SA-node impulse to the left atrium is {{c1::Bachmann's bundle}}."},
  {"id":"acomp-cond-sanode-s04-01","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Place SVC cannulation, snares and atriotomies with the subepicardial {{c1::SA node}} and its variable artery in mind."},
  {"id":"acomp-cond-sanode-s04-02","region":"cond-sanode","category":"conduction","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Injury may present as junctional rhythm or {{c1::persistent sinus-node dysfunction}} after an otherwise uncomplicated operation."},
  {"id":"acomp-cond-avnode-s01-01","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Triangle of Koch","text":"In Triangle of Koch, {{c1::Hinge of the septal leaflet of the tricuspid valve}} is the anteroinferior border."},
  {"id":"acomp-cond-avnode-s01-02","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Triangle of Koch","text":"In Triangle of Koch, {{c1::Superior margin of the coronary sinus ostium}} is the posterior border."},
  {"id":"acomp-cond-avnode-s01-03","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Triangle of Koch","text":"The AV node sits at the {{c1::apex of the triangle}}, where all three borders converge, just superior to the coronary sinus ostium."},
  {"id":"acomp-cond-avnode-s02-01","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"AV Node Blood Supply","text":"The {{c1::AV nodal artery}} arises from the RCA in 85–90% of patients and from the circumflex artery in 10–15%."},
  {"id":"acomp-cond-avnode-s02-02","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"AV Node Blood Supply","text":"It typically arises at the {{c1::crux cordis}} — the posterior junction of the four cardiac chambers — in right-dominant systems."},
  {"id":"acomp-cond-avnode-s02-03","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"AV Node Blood Supply","text":"In 85–90% of patients, the AV nodal artery arises from the {{c1::RCA}}."},
  {"id":"acomp-cond-avnode-s03-01","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"The triangle of Koch is a no-guessing zone: identify the {{c1::coronary-sinus ostium}}, tendon of Todaro and septal tricuspid hinge before placing sutures near its apex."},
  {"id":"acomp-cond-avnode-s03-02","region":"cond-avnode","category":"conduction","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Before placing sutures near its apex, identify the coronary-sinus ostium, tendon of Todaro, and septal tricuspid hinge within the {{c1::triangle of Koch}}."},
  {"id":"acomp-cond-his-bundle-s01-01","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Bundle of His","text":"The bundle of His penetrates the {{c1::central fibrous body}} to reach the membranous septum, lying on the crest of the muscular ventricular septum just beneath the commissure between the right and non-coronary cusps of the aortic valve."},
  {"id":"acomp-cond-his-bundle-s01-02","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Bundle of His","text":"This proximity explains why aortic valve surgery risks complete heart block if deep sutures are placed at the {{c1::RCC-NCC commissure}}."},
  {"id":"acomp-cond-his-bundle-s02-01","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Left Bundle Branch","text":"The left bundle branch divides into {{c1::anterior and posterior fascicles}}, which run sub-endocardially down the septal surface of the left ventricle to the apex."},
  {"id":"acomp-cond-his-bundle-s02-02","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Left Bundle Branch","text":"Left anterior fascicular block is common with {{c1::LAD}} territory disease involving the proximal septum."},
  {"id":"acomp-cond-his-bundle-s03-01","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Right Bundle Branch","text":"The right bundle branch runs on the {{c1::right side of the ventricular septum}} toward the base of the medial papillary muscle of the tricuspid valve, traversing the RV cavity through the moderator band (septomarginal trabeculation)."},
  {"id":"acomp-cond-his-bundle-s03-02","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Right Bundle Branch","text":"The {{c1::moderator band}} is a key surgical landmark in the RV."},
  {"id":"acomp-cond-his-bundle-s04-01","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"The penetrating bundle is vulnerable at the {{c1::membranous septum}} in AVR, root surgery and VSD closure."},
  {"id":"acomp-cond-his-bundle-s04-02","region":"cond-his-bundle","category":"conduction","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"{{c1::New postoperative AV block}} should be interpreted against the precise site of debridement and suturing."},
  {"id":"acomp-cor-leftmain-s01-01","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"The LMCA originates from the {{c1::left coronary ostium}}, which sits just above the left aortic valve leaflet within the left coronary sinus of Valsalva."},
  {"id":"acomp-cor-leftmain-s01-02","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"It courses {{c1::anteriorly and inferiorly}}, passing between the pulmonary trunk anteriorly and the left atrial appendage posteriorly, before bifurcating."},
  {"id":"acomp-cor-leftmain-s01-03","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"It typically measures {{c1::10–40 mm}} in length."},
  {"id":"acomp-cor-leftmain-s02-01","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Bifurcation and Variants","text":"The LMCA typically {{c1::bifurcates}} into the left anterior descending (LAD) and circumflex (Cx) arteries."},
  {"id":"acomp-cor-leftmain-s02-02","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Bifurcation and Variants","text":"In some patients it {{c1::trifurcates}}, giving rise to an additional ramus intermedius (intermediate branch), which supplies the lateral LV wall like an obtuse marginal or diagonal artery."},
  {"id":"acomp-cor-leftmain-s02-03","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Bifurcation and Variants","text":"Disease at the {{c1::LMCA ostium}} is particularly dangerous given the territory at risk."},
  {"id":"acomp-cor-leftmain-s03-01","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Before root cardioplegia or coronary-button mobilization, identify {{c1::ostial height}}, left-main length and bifurcation."},
  {"id":"acomp-cor-leftmain-s03-02","region":"cor-leftmain","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"A {{c1::short left main}} leaves less margin between an ostial instrument and the bifurcation."},
  {"id":"acomp-cor-lad-s01-01","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Segments","text":"The LAD courses {{c1::anteriorly and inferiorly}} in the anterior interventricular groove toward the cardiac apex."},
  {"id":"acomp-cor-lad-s01-02","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Segments","text":"{{c1::Proximal third}}: origin to the first septal perforator."},
  {"id":"acomp-cor-lad-s02-01","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Diagonal Branches","text":"Usually {{c1::2–6 diagonal branches}} arise from the LAD and course obliquely across the free wall to supply the anterolateral LV wall."},
  {"id":"acomp-cor-lad-s02-02","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Diagonal Branches","text":"They are key bypass targets in {{c1::mid-LAD disease}}."},
  {"id":"acomp-cor-lad-s03-01","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Septal Perforator Arteries","text":"Usually {{c1::3–5 septal perforators}} arise perpendicularly from the LAD and supply the anterior two-thirds of the interventricular septum."},
  {"id":"acomp-cor-lad-s03-02","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Septal Perforator Arteries","text":"The {{c1::first septal perforator}} is the largest and runs toward the medial papillary muscle of the tricuspid valve."},
  {"id":"acomp-cor-lad-s04-01","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"During CABG, trace the {{c1::LAD}} beyond the obstructive lesion and avoid mistaking a large diagonal for the main vessel."},
  {"id":"acomp-cor-lad-s04-02","region":"cor-lad","category":"coronary","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"An {{c1::intramyocardial segment}} may require ultrasound or careful distal-to-proximal dissection."},
  {"id":"acomp-cor-circumflex-s01-01","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Termination","text":"The Cx runs in the {{c1::left atrioventricular groove}}."},
  {"id":"acomp-cor-circumflex-s01-02","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Termination","text":"In {{c1::85–90%}} of patients (right-dominant anatomy) it terminates before reaching the posterior interventricular groove."},
  {"id":"acomp-cor-circumflex-s01-03","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Termination","text":"In {{c1::10–15%}} (left-dominant) it continues as the posterior descending artery (PDA)."},
  {"id":"acomp-cor-circumflex-s02-01","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"{{c1::Obtuse marginal (OM) branches}}: supply the lateral LV wall including the anterolateral papillary muscle."},
  {"id":"acomp-cor-circumflex-s02-02","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"{{c1::SA nodal artery}}: from Cx in 45% of patients (from RCA in 55%)"},
  {"id":"acomp-cor-circumflex-s02-03","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"{{c1::AV nodal artery}}: from Cx in 10–15% (from RCA in 85–90%)"},
  {"id":"acomp-cor-circumflex-s03-01","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"The {{c1::circumflex}} is both a graft system and a structure at risk during mitral surgery."},
  {"id":"acomp-cor-circumflex-s03-02","region":"cor-circumflex","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"{{c1::Deep posterior-annular sutures}} can distort or occlude it, particularly in left-dominant anatomy."},
  {"id":"acomp-cor-rca-s01-01","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course","text":"The RCA originates from the {{c1::right coronary ostium}} in the right coronary sinus."},
  {"id":"acomp-cor-rca-s01-02","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course","text":"It courses {{c1::anteriorly and laterally}} into the right atrioventricular groove, descending inferiorly to the acute margin of the RV."},
  {"id":"acomp-cor-rca-s02-01","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"{{c1::Infundibular (conus) branch}}: first branch, courses over the RVOT."},
  {"id":"acomp-cor-rca-s02-02","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"{{c1::SA nodal artery}}: from RCA in 55% of patients."},
  {"id":"acomp-cor-rca-s03-01","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Coronary Dominance","text":"Dominance is defined by the artery from which the {{c1::PDA}} originates."},
  {"id":"acomp-cor-rca-s03-02","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Coronary Dominance","text":"Right-dominant in {{c1::80–85%}}, left-dominant in 10–15%, codominant in ~5%."},
  {"id":"acomp-cor-rca-s04-01","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"The {{c1::RCA}} is exposed in the right AV groove but its PDA and posterolateral targets lie inferiorly."},
  {"id":"acomp-cor-rca-s04-02","region":"cor-rca","category":"coronary","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Proximal injury can affect {{c1::RV perfusion}} and both nodal arteries; distal consequences depend on dominance."},
  {"id":"acomp-cor-veins-s01-01","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Coronary Sinus","text":"The coronary sinus is a continuation of the {{c1::great cardiac vein}}, running in the left atrioventricular groove alongside the circumflex artery."},
  {"id":"acomp-cor-veins-s01-02","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Coronary Sinus","text":"The transition is marked by the {{c1::valve of Vieussens}} and the entry of the oblique vein of the left atrium (vein of Marshall) — an electrophysiologically important structure (AF triggers)."},
  {"id":"acomp-cor-veins-s01-03","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Coronary Sinus","text":"The {{c1::coronary sinus}} ostium opens into the right atrium, guarded by the Thebesian valve."},
  {"id":"acomp-cor-veins-s02-01","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Cardiac Veins","text":"{{c1::Great cardiac vein}}: runs in the anterior interventricular groove alongside the LAD, then into the left AV groove alongside the Cx; drains to the coronary sinus."},
  {"id":"acomp-cor-veins-s02-02","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Cardiac Veins","text":"{{c1::Middle cardiac vein}}: runs in the posterior interventricular groove alongside the PDA; used for retrograde cardioplegia delivery."},
  {"id":"acomp-cor-veins-s02-03","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Cardiac Veins","text":"{{c1::Small cardiac vein}}: runs in the right AV groove alongside the RCA; drains to the right end of the coronary sinus."},
  {"id":"acomp-cor-veins-s03-01","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"The {{c1::coronary sinus}} is the route for retrograde cardioplegia and a landmark for the triangle of Koch."},
  {"id":"acomp-cor-veins-s03-02","region":"cor-veins","category":"coronary","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"{{c1::Cannula depth and pressure}} matter: malposition gives incomplete protection, while excessive pressure can injure the sinus."},
  {"id":"acomp-val-aortic-s01-01","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Leaflet Anatomy","text":"The aortic valve has three semilunar leaflets: the {{c1::right coronary cusp (RCC)}}, the left coronary cusp (LCC), and the non-coronary (posterior) cusp (NCC)."},
  {"id":"acomp-val-aortic-s01-02","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Leaflet Anatomy","text":"Each leaflet has a fibrous core thickened centrally at its free edge, forming the {{c1::nodule of Arantius}}, which aids coaptation and valve sealing."},
  {"id":"acomp-val-aortic-s02-01","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Competence and Root Components","text":"Aortic valve competence depends on: the valve leaflets, the {{c1::sinuses of Valsalva}} (right, left, non-coronary), the sinotubular junction, the anatomical ventriculo-arterial junction, and the basal ring."},
  {"id":"acomp-val-aortic-s02-02","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Competence and Root Components","text":"The haemodynamic boundary between ventricle and aorta is marked by the crown-shaped line of {{c1::leaflet attachments}}, not the anatomical junction — creating triangles of arterial wall on the ventricular side."},
  {"id":"acomp-val-aortic-s03-01","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Surgical Relations","text":"{{c1::NCC}}: abuts the interatrial septum and AV node region."},
  {"id":"acomp-val-aortic-s03-02","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Surgical Relations","text":"{{c1::RCC}}: adjacent to the RV and membranous septum (bundle of His lies just below the RCC-NCC commissure)"},
  {"id":"acomp-val-aortic-s04-01","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Read aortic-valve anatomy as a {{c1::root unit}}: cusp quality, commissural height, annular support, sinuses and sinotubular junction."},
  {"id":"acomp-val-aortic-s04-02","region":"val-aortic","category":"valves","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"The {{c1::mechanism of failure}} determines whether repair, isolated replacement or root surgery is anatomically sound."},
  {"id":"acomp-val-pulmonary-s01-01","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Anatomy","text":"The pulmonary valve has three semilunar leaflets: {{c1::right cusp}}, left cusp, and anterior cusp."},
  {"id":"acomp-val-pulmonary-s01-02","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Anatomy","text":"Competence depends on the same structures as the aortic valve: leaflets, sinuses, commissures, and the {{c1::sinotubular junction}}."},
  {"id":"acomp-val-pulmonary-s01-03","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Anatomy","text":"The {{c1::pulmonary root}} is the structural blueprint used in the Ross procedure."},
  {"id":"acomp-val-pulmonary-s02-01","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Ross Procedure Risk","text":"During pulmonary autograft harvest, the {{c1::first septal perforator of the LAD}} is at risk because it lies immediately beneath the RVOT and pulmonary valve."},
  {"id":"acomp-val-pulmonary-s02-02","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Ross Procedure Risk","text":"Injury can cause {{c1::anterior septal ischaemia}} or infarction."},
  {"id":"acomp-val-pulmonary-s02-03","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Ross Procedure Risk","text":"During pulmonary autograft harvest, the first septal perforator lies immediately beneath the {{c1::RVOT and pulmonary valve}}."},
  {"id":"acomp-val-pulmonary-s03-01","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Pulmonary-root dissection is deceptively close to the {{c1::LAD}} septal branches and left main region."},
  {"id":"acomp-val-pulmonary-s03-02","region":"val-pulmonary","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"In a {{c1::Ross procedure}}, the autograft must be harvested with enough muscle for integrity but not enough depth to injure coronary supply."},
  {"id":"acomp-val-mitral-s01-01","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Leaflets","text":"{{c1::Anterior (aortic) leaflet}}: shares fibrous continuity with the aortic valve (aortic-mitral curtain)."},
  {"id":"acomp-val-mitral-s01-02","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Leaflets","text":"{{c1::Posterior (mural) leaflet}}: subdivided by clefts into scallops P1 (anterolateral), P2 (middle), and P3 (posteromedial), with corresponding A1, A2, A3 areas on the anterior leaflet."},
  {"id":"acomp-val-mitral-s02-01","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Annulus","text":"The posterior annulus accounts for {{c1::two-thirds}} of the circumference; the anterior annulus (fibrous, part of the central fibrous body) accounts for one-third."},
  {"id":"acomp-val-mitral-s02-02","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Annulus","text":"The annulus contracts by {{c1::20–40%}} in systole, aiding competence."},
  {"id":"acomp-val-mitral-s03-01","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Papillary Muscles and Chordae","text":"{{c1::Anterolateral PM}}: single head, dual blood supply from the circumflex artery (and diagonal branches) — more resistant to ischaemia."},
  {"id":"acomp-val-mitral-s03-02","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Papillary Muscles and Chordae","text":"{{c1::Posteromedial PM}}: multiple heads, single blood supply from the RCA — vulnerable to RCA occlusion, causing papillary muscle rupture and acute MR."},
  {"id":"acomp-val-mitral-s04-01","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"A repair is a geometric diagnosis: identify the {{c1::diseased scallop}}, chordal lesion, annular distortion and ventricular mechanism before selecting resection, neochordae or annuloplasty."},
  {"id":"acomp-val-mitral-s04-02","region":"val-mitral","category":"valves","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"In Why this anatomy matters in theatre, Preserve {{c1::leaflet tissue and subvalvular continuity}} whenever possible."},
  {"id":"acomp-val-tricuspid-s01-01","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Leaflets","text":"{{c1::Anterior leaflet}}: the largest and most important surgically."},
  {"id":"acomp-val-tricuspid-s01-02","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Leaflets","text":"{{c1::Septal leaflet}}: the most important from a conduction system risk perspective."},
  {"id":"acomp-val-tricuspid-s02-01","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Papillary Muscles","text":"{{c1::Anterior PM}} (largest): arises from the moderator band (septomarginal trabeculation); supports the anterior leaflet and the anterior-posterior zone of apposition."},
  {"id":"acomp-val-tricuspid-s02-02","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Papillary Muscles","text":"{{c1::Medial PM of Lancisi}}: supports the septal leaflet and septal-anterior zone of apposition; the right bundle branch passes through it — injury risks RBBB or complete heart block."},
  {"id":"acomp-val-tricuspid-s03-01","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Conduction System Relations","text":"During tricuspid valve surgery, the conduction system is at most risk near the {{c1::septal leaflet hinge}} and the anteroseptal commissure, where the bundle of His is closest to the valve."},
  {"id":"acomp-val-tricuspid-s03-02","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Conduction System Relations","text":"Sutures placed here can cause {{c1::complete heart block}}."},
  {"id":"acomp-val-tricuspid-s04-01","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"The {{c1::septal annulus}} is fixed and closely related to the conduction axis, while the anterior and posterior annulus dilate."},
  {"id":"acomp-val-tricuspid-s04-02","region":"val-tricuspid","category":"valves","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Ring sutures therefore require unequal confidence: generous remodeling laterally, deliberate {{c1::shallow bites septally}}."},
  {"id":"acomp-ves-aorta-s01-01","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Descending Thoracic Aorta","text":"The descending thoracic aorta commences just distal to the origin of the {{c1::left subclavian artery}}, as a continuation of the aortic arch."},
  {"id":"acomp-ves-aorta-s01-02","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Descending Thoracic Aorta","text":"It terminates by passing through the {{c1::aortic hiatus at T12}} alongside the thoracic duct and azygos vein, to continue as the abdominal aorta."},
  {"id":"acomp-ves-aorta-s01-03","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Descending Thoracic Aorta","text":"It lies initially to the left of the {{c1::thoracic vertebrae}}, gradually moving medially to lie anterior to the vertebral column as it descends."},
  {"id":"acomp-ves-aorta-s02-01","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches of the Descending Thoracic Aorta","text":"In Branches of the Descending Thoracic Aorta, {{c1::Posterior intercostal arteries}} is the 3rd–11th spaces arise directly from the descending aorta."},
  {"id":"acomp-ves-aorta-s02-02","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches of the Descending Thoracic Aorta","text":"The {{c1::superior phrenic arteries}} are branches of the descending thoracic aorta."},
  {"id":"acomp-ves-aorta-s02-03","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches of the Descending Thoracic Aorta","text":"Posterior intercostal arteries (3rd–11th spaces arise directly from the {{c1::descending aorta}})"},
  {"id":"acomp-ves-aorta-s03-01","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Aortic anatomy sets the {{c1::cannulation}}, clamp and cerebral-protection plan."},
  {"id":"acomp-ves-aorta-s03-02","region":"ves-aorta","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Disease at one segment may force inflow or occlusion into another, so imaging must be read from root through the {{c1::access vessels}} rather than at the aneurysm alone."},
  {"id":"acomp-ves-femoral-s01-01","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Common Femoral Artery","text":"The common femoral artery (CFA) is a continuation of the {{c1::external iliac artery}}, commencing just beneath the inguinal ligament."},
  {"id":"acomp-ves-femoral-s01-02","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Common Femoral Artery","text":"It is located at the {{c1::mid-inguinal point}} — halfway between the anterior superior iliac spine (ASIS) and the symphysis pubis."},
  {"id":"acomp-ves-femoral-s02-01","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Femoral Sheath Contents","text":"The {{c1::femoral nerve}} lies lateral to the artery but outside the femoral sheath."},
  {"id":"acomp-ves-femoral-s02-02","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Femoral Sheath Contents","text":"The {{c1::femoral vein}} lies medial to the artery."},
  {"id":"acomp-ves-femoral-s03-01","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Common Femoral Vein","text":"The common femoral vein forms from the confluence of the deep and superficial femoral veins and continues as the {{c1::external iliac vein}} when it passes under the inguinal ligament."},
  {"id":"acomp-ves-femoral-s03-02","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Common Femoral Vein","text":"The long saphenous vein joins at the {{c1::saphenofemoral junction}}, 3 cm inferior and 3 cm medial to the femoral arterial pulse."},
  {"id":"acomp-ves-femoral-s04-01","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Access the {{c1::common femoral artery}} over the femoral head, below the inguinal ligament and above the profunda bifurcation."},
  {"id":"acomp-ves-femoral-s04-02","region":"ves-femoral","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Too high risks {{c1::retroperitoneal bleeding}}; too low risks small-vessel injury and limb ischaemia."},
  {"id":"acomp-ves-saphenous-s01-01","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Long Saphenous Vein","text":"The LSV commences just {{c1::anterior and superior to the medial malleolus}}."},
  {"id":"acomp-ves-saphenous-s01-02","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Long Saphenous Vein","text":"It continues up the medial aspect of the lower leg with the {{c1::saphenous nerve}}, turns slightly posteriorly at the superior aspect of the gastrocnemius, then passes medial to the knee joint (5 cm posterior to the medial aspect of the patella)."},
  {"id":"acomp-ves-saphenous-s02-01","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Short Saphenous Vein","text":"The short saphenous vein (SSV) starts {{c1::2 cm posterior to the lateral malleolus}}, courses superiorly superficial to the gastrocnemius in the midline of the posterior calf, running with the sural nerve (risk of lateral foot numbness during harvest), and terminates by draining into the popliteal vein just below the knee."},
  {"id":"acomp-ves-saphenous-s02-02","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Short Saphenous Vein","text":"The short saphenous vein travels with the {{c1::sural nerve}}, creating a risk of lateral foot numbness during harvest."},
  {"id":"acomp-ves-saphenous-s03-01","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Nerve Injury During Harvest","text":"The {{c1::saphenous nerve}} (a branch of the femoral nerve) travels with the LSV throughout its course."},
  {"id":"acomp-ves-saphenous-s03-02","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Nerve Injury During Harvest","text":"Injury causes sensory loss over the {{c1::medial aspect of the leg and foot}} — the most common neurological complication of LSV harvest."},
  {"id":"acomp-ves-saphenous-s04-01","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Mark the vein before incision, {{c1::preserve orientation}}, avoid high-pressure distension and protect the accompanying nerve."},
  {"id":"acomp-ves-saphenous-s04-02","region":"ves-saphenous","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Once removed, check for branches, varicosity and calibre before treating it as a {{c1::conduit}}."},
  {"id":"acomp-ves-lima-s01-01","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"The LIMA originates from the {{c1::first part of the subclavian artery}}, medial to scalenus anterior."},
  {"id":"acomp-ves-lima-s01-02","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"It lies in the neurovascular plane between the {{c1::transversus thoracis muscle}} and the internal intercostal muscle layers."},
  {"id":"acomp-ves-lima-s02-01","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"{{c1::Pericardiophrenic artery}}: supplies the phrenic nerve and lateral pericardium — the reason phrenic nerve injury can occur during LIMA harvest."},
  {"id":"acomp-ves-lima-s02-02","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"The LIMA branches that supply the overlying pectoralis major are the {{c1::perforating branches}}."},
  {"id":"acomp-ves-lima-s03-01","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Termination","text":"The LIMA terminates around the {{c1::6th intercostal space}} by dividing into: Superior epigastric artery: supplies the superior anterior abdominal wall and rectus abdominis."},
  {"id":"acomp-ves-lima-s03-02","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Termination","text":"{{c1::Musculophrenic artery}}: supplies 6th–10th intercostal spaces; can occasionally be used as a conduit."},
  {"id":"acomp-ves-lima-s04-01","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"{{c1::LIMA}} harvest balances conduit length against chest-wall perfusion."},
  {"id":"acomp-ves-lima-s04-02","region":"ves-lima","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Control branches close to the artery without {{c1::thermal injury}}, protect the phrenic nerve, and confirm a tension-free lie to the LAD after lung inflation."},
  {"id":"acomp-ves-radial-s01-01","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"The radial artery commences as one of the two terminal branches of the {{c1::brachial artery}}, medial to the biceps tendon."},
  {"id":"acomp-ves-radial-s01-02","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"It is divided into three parts: Proximal: origin to {{c1::distal antecubital fossa}}."},
  {"id":"acomp-ves-radial-s02-01","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Termination and Branches","text":"The radial artery terminates at the {{c1::radial styloid process}} and continues as the deep palmar artery, which anastomoses with the superficial palmar arch from the ulnar artery."},
  {"id":"acomp-ves-radial-s02-02","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Termination and Branches","text":"Branches include the {{c1::recurrent radial artery}}, superficial palmar artery, and muscular branches."},
  {"id":"acomp-ves-radial-s03-01","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Nerves at Risk During Harvest","text":"{{c1::Lateral cutaneous nerve of the forearm}} (C5–6): sensory to the lateral forearm."},
  {"id":"acomp-ves-radial-s03-02","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Nerves at Risk During Harvest","text":"{{c1::Superficial radial nerve}} (C7–8): crosses the anatomical snuffbox; damage causes numbness over the dorsum of the thumb base and thenar eminence."},
  {"id":"acomp-ves-radial-s04-01","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Preoperative assessment must {{c1::prove adequate ulnar collateral flow}} and exclude dialysis needs or forearm disease."},
  {"id":"acomp-ves-radial-s04-02","region":"ves-radial","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"During harvest, prevent spasm, protect {{c1::superficial sensory nerves}} and preserve the artery's endothelial surface."},
  {"id":"acomp-ves-phrenic-s01-01","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"The phrenic nerve originates from nerve roots {{c1::C3, C4, and C5}} (mnemonic: C3, 4, 5 keeps the diaphragm alive)."},
  {"id":"acomp-ves-phrenic-s01-02","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Origin and Course","text":"It courses down through the neck lying {{c1::anterior to scalenus anterior}}, passes posterior to the subclavian artery, and then medial to the internal mammary artery to lie on the lateral surface of the pericardium."},
  {"id":"acomp-ves-phrenic-s02-01","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Diaphragmatic Entry","text":"The {{c1::right phrenic nerve}} passes through the inferior vena caval opening at the level of T8."},
  {"id":"acomp-ves-phrenic-s02-02","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Diaphragmatic Entry","text":"The {{c1::left phrenic nerve pierces the muscular part}} of the left hemi-diaphragm."},
  {"id":"acomp-ves-phrenic-s03-01","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Function","text":"In Function, Sensory: to the {{c1::diaphragm and anterior chest and abdominal wall}}."},
  {"id":"acomp-ves-phrenic-s03-02","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Function","text":"Referred pain to the {{c1::shoulder tip}} can occur with diaphragmatic or pericardial irritation via the phrenic nerve."},
  {"id":"acomp-ves-phrenic-s04-01","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Keep pericardiotomy and traction sutures anterior to the nerve, avoid direct cautery near the {{c1::pericardiophrenic bundle}}, and remember that cold injury can occur even without transection."},
  {"id":"acomp-ves-phrenic-s04-02","region":"ves-phrenic","category":"vessels","subtype":"structures","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Why this anatomy matters in theatre","text":"Cold exposure can injure the phrenic nerve even without {{c1::transection}}."},
  {"id":"acomp-ves-axillary-s01-01","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Parts","text":"The axillary artery is a direct continuation of the {{c1::subclavian artery}} commencing at the outer edge of the 1st rib."},
  {"id":"acomp-ves-axillary-s01-02","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Parts","text":"It terminates at the {{c1::lower border of teres major}}, continuing as the brachial artery."},
  {"id":"acomp-ves-axillary-s01-03","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Course and Parts","text":"It is divided into three parts by {{c1::pectoralis minor}}: the 1st part lies above, the 2nd part behind, and the 3rd part below the muscle (Rule of 1-2-3: 1 branch in part 1, 2 in part 2, 3 in part 3)."},
  {"id":"acomp-ves-axillary-s02-01","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"Part 2: {{c1::thoracoacromial artery}}, lateral thoracic artery."},
  {"id":"acomp-ves-axillary-s02-02","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"Part 3: {{c1::subscapular artery}} (largest branch), anterior and posterior humeral circumflex arteries."},
  {"id":"acomp-ves-axillary-s02-03","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Branches","text":"The sole branch of axillary artery part 1 is the {{c1::highest thoracic artery}}."},
  {"id":"acomp-ves-axillary-s03-01","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"A {{c1::side graft}} to the right axillary artery often provides controlled inflow and antegrade cerebral perfusion."},
  {"id":"acomp-ves-axillary-s03-02","region":"ves-axillary","category":"vessels","subtype":"structures","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Why this anatomy matters in theatre","text":"Dissection stays close to the artery to reduce {{c1::brachial-plexus injury}}, and distal limb perfusion must remain part of the plan."},
  {"id":"acomp-cham-surface-orientation-s01-01","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Start here — orient the heart in the chest","text":"The {{c1::right ventricle}} forms most of the anterior or sternocostal surface; the left ventricle forms the left border, apex, and most of the diaphragmatic surface; the right atrium forms the right border; and the left atrium forms the posterior base."},
  {"id":"acomp-cham-surface-orientation-s01-02","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Start here — orient the heart in the chest","text":"The {{c1::cardiac long axis}} runs from the right shoulder toward the left hip."},
  {"id":"acomp-cham-surface-orientation-s01-03","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Start here — orient the heart in the chest","text":"This explains why a {{c1::midline}} sternotomy exposes the RV and ascending aorta immediately but not the mitral valve or posterior descending artery."},
  {"id":"acomp-cham-surface-orientation-s02-01","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"The operative view after the pericardium opens","text":"With the {{c1::pericardium}} suspended, the surgeon sees the right atrial appendage to the right, the ascending aorta centrally, the pulmonary trunk to its left, and the RVOT sweeping toward the pulmonary valve."},
  {"id":"acomp-cham-surface-orientation-s02-02","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"The operative view after the pericardium opens","text":"The {{c1::LAD}} marks the anterior interventricular groove and separates the RV from the LV."},
  {"id":"acomp-cham-surface-orientation-s02-03","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"The operative view after the pericardium opens","text":"The right and left atrioventricular grooves mark the {{c1::junctions between atria}} and ventricles and carry the RCA and circumflex systems."},
  {"id":"acomp-cham-surface-orientation-s03-01","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Mobilizing the heart — what moves and what does not","text":"The {{c1::apex}} and ventricular free walls can be elevated, but the great veins and atrial attachments tether the base."},
  {"id":"acomp-cham-surface-orientation-s03-02","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Mobilizing the heart — what moves and what does not","text":"Lifting the heart to expose the obtuse marginal or PDA territory can kink the venae cavae, reduce venous return, compress the {{c1::RV}}, and cause abrupt hypotension—especially during off-pump CABG."},
  {"id":"acomp-cham-surface-orientation-s03-03","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Mobilizing the heart — what moves and what does not","text":"A {{c1::deep pericardial traction suture}} improves exposure but must not injure the phrenic nerve."},
  {"id":"acomp-cham-surface-orientation-s04-01","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"How surface anatomy guides the operation","text":"Anterior targets such as the {{c1::LAD}} are usually accessible with little displacement."},
  {"id":"acomp-cham-surface-orientation-s04-02","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"How surface anatomy guides the operation","text":"Lateral circumflex targets require the {{c1::apex}} to be elevated and rotated rightward; inferior RCA/PDA targets require cephalad displacement."},
  {"id":"acomp-cham-surface-orientation-s04-03","region":"cham-surface-orientation","category":"chambers","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"How surface anatomy guides the operation","text":"The surface map therefore predicts both technical exposure and the {{c1::haemodynamic price}} of obtaining it."},
  {"id":"acomp-cham-pericardial-access-s01-01","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"From skin to mediastinum","text":"A {{c1::median sternotomy}} passes through skin, subcutaneous tissue, sternal periosteum and sternum into anterior mediastinal tissue."},
  {"id":"acomp-cham-pericardial-access-s01-02","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"From skin to mediastinum","text":"The {{c1::paired internal thoracic arteries}} run roughly 1–2 cm lateral to the sternal edges."},
  {"id":"acomp-cham-pericardial-access-s01-03","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"From skin to mediastinum","text":"Inferiorly, the {{c1::RV}} may lie only millimetres behind the sternum; superiorly, the left brachiocephalic vein crosses behind the manubrium and in front of the arch branches."},
  {"id":"acomp-cham-pericardial-access-s02-01","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Opening the pericardium","text":"The pericardium is usually opened longitudinally several centimetres {{c1::anterior to the right phrenic nerve}}, from near the diaphragm toward the aortic reflection."},
  {"id":"acomp-cham-pericardial-access-s02-02","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Opening the pericardium","text":"Stay sutures retract the edges and create the {{c1::operative well}}."},
  {"id":"acomp-cham-pericardial-access-s02-03","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Opening the pericardium","text":"Opening too lateral risks the {{c1::phrenic nerve}} and pericardiophrenic vessels; opening too close to the great vessels can compromise later cannulation or closure."},
  {"id":"acomp-cham-pericardial-access-s03-01","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Redo sternotomy — anatomy has changed","text":"After prior surgery, the {{c1::RV}}, aorta, vein grafts, or right internal thoracic artery may be adherent to the posterior sternum."},
  {"id":"acomp-cham-pericardial-access-s03-02","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Redo sternotomy — anatomy has changed","text":"{{c1::Preoperative CT}} identifies the structure closest to each sternal level and whether peripheral cannulation should be established before re-entry."},
  {"id":"acomp-cham-pericardial-access-s03-03","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Redo sternotomy — anatomy has changed","text":"The most dangerous phase is the {{c1::final division of the posterior table}}, when an adherent cardiac structure can be opened before control is available."},
  {"id":"acomp-cham-pericardial-access-s04-01","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"The bailout map","text":"Femoral or {{c1::axillary arterial access}} and femoral venous access provide routes to cardiopulmonary bypass before or during a difficult re-entry."},
  {"id":"acomp-cham-pericardial-access-s04-02","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"The bailout map","text":"Knowledge of {{c1::prior graft}} routing is crucial: an intact LIMA often crosses near the left upper mediastinum and injury can produce immediate LAD ischaemia."},
  {"id":"acomp-cham-pericardial-access-s04-03","region":"cham-pericardial-access","category":"chambers","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"The bailout map","text":"Never assume the {{c1::retrosternal plane}} is empty in a redo chest; CT anatomy should drive the access plan."},
  {"id":"acomp-cor-territories-targets-s01-01","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Start here — translate artery into myocardium","text":"The {{c1::LAD}} supplies the anterior LV, apex and anterior two-thirds of the septum through diagonal and septal branches."},
  {"id":"acomp-cor-territories-targets-s01-02","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Start here — translate artery into myocardium","text":"The circumflex supplies the lateral and {{c1::posterolateral LV}} through obtuse marginal branches."},
  {"id":"acomp-cor-territories-targets-s01-03","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Start here — translate artery into myocardium","text":"The {{c1::RCA}} supplies the RV and, in right dominance, the inferior LV, posterior septum and AV node through the PDA and posterolateral branches."},
  {"id":"acomp-cor-territories-targets-s02-01","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Name the surgical target correctly","text":"Targets are described by the {{c1::branch actually opened}}: LAD, diagonal, OM, PDA, or posterolateral branch—not merely by the parent coronary system."},
  {"id":"acomp-cor-territories-targets-s02-02","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Name the surgical target correctly","text":"A {{c1::suitable site}} is distal to important stenosis, usually at least about 1.5 mm in calibre, and has a relatively healthy wall with useful runoff."},
  {"id":"acomp-cor-territories-targets-s02-03","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Name the surgical target correctly","text":"The {{c1::angiographic target}} and the visible epicardial vessel may differ because fat, myocardial bridging, calcification, and intramyocardial segments obscure the course."},
  {"id":"acomp-cor-territories-targets-s03-01","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Exposure and conduit routing","text":"The {{c1::LAD}} is approached anteriorly and usually receives the in-situ LIMA."},
  {"id":"acomp-cor-territories-targets-s03-02","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Exposure and conduit routing","text":"{{c1::OM branches}} require rightward rotation and elevation of the apex."},
  {"id":"acomp-cor-territories-targets-s03-03","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Exposure and conduit routing","text":"The {{c1::PDA}} lies in the posterior interventricular groove and is exposed by elevating the inferior heart."},
  {"id":"acomp-cor-territories-targets-s04-01","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"The anatomy of a durable anastomosis","text":"The {{c1::arteriotomy}} should enter true lumen in a segment with acceptable wall quality."},
  {"id":"acomp-cor-territories-targets-s04-02","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"The anatomy of a durable anastomosis","text":"{{c1::Heavy calcification}} prevents a clean needle bite; diffuse distal disease creates poor runoff; and grafting a mildly stenosed vessel creates competitive flow."},
  {"id":"acomp-cor-territories-targets-s04-03","region":"cor-territories-targets","category":"coronary","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"The anatomy of a durable anastomosis","text":"Each problem is an anatomical reason for {{c1::early failure}} even when the suture line appears technically neat."},
  {"id":"acomp-cor-coronary-variants-s01-01","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Separate ostia, ramus and dual LAD","text":"The left main may be absent, with {{c1::separate LAD}} and circumflex ostia."},
  {"id":"acomp-cor-coronary-variants-s01-02","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Separate ostia, ramus and dual LAD","text":"A {{c1::ramus intermedius}} arises when the left main trifurcates and supplies the lateral wall."},
  {"id":"acomp-cor-coronary-variants-s01-03","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Separate ostia, ramus and dual LAD","text":"Dual-LAD patterns include a {{c1::short LAD}} ending high in the groove and a long LAD reaching the distal groove by an unusual course."},
  {"id":"acomp-cor-coronary-variants-s02-01","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Anomalous aortic origin","text":"An anomalous coronary arising from the {{c1::opposite sinus}} may travel between the aorta and pulmonary artery, within the aortic wall, behind the aorta, in front of the pulmonary artery, or through the septum."},
  {"id":"acomp-cor-coronary-variants-s02-02","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Anomalous aortic origin","text":"High-risk features include an intramural segment, {{c1::slit-like ostium}}, acute take-off angle, and interarterial course."},
  {"id":"acomp-cor-coronary-variants-s02-03","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Anomalous aortic origin","text":"Repair strategy may involve unroofing, reimplantation, pulmonary-artery translocation, or selective bypass depending on the {{c1::exact anatomy}}."},
  {"id":"acomp-cor-coronary-variants-s03-01","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Intramyocardial and bridged vessels","text":"A myocardial bridge covers an epicardial coronary segment, most often the {{c1::LAD}}."},
  {"id":"acomp-cor-coronary-variants-s03-02","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Intramyocardial and bridged vessels","text":"During CABG, an {{c1::intramyocardial LAD}} can be difficult to locate and careless dissection risks entering the RV because the anterior septum may be thin beneath the groove."},
  {"id":"acomp-cor-coronary-variants-s03-03","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Intramyocardial and bridged vessels","text":"{{c1::Angiography and epicardial ultrasound}} can help define the buried segment."},
  {"id":"acomp-cor-coronary-variants-s04-01","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Cardioplegia implications","text":"Separate or {{c1::anomalous ostia}} may not receive reliable antegrade root cardioplegia."},
  {"id":"acomp-cor-coronary-variants-s04-02","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Cardioplegia implications","text":"After the {{c1::aorta}} is opened, direct ostial cardioplegia must be delivered deliberately and without traumatic cannulation."},
  {"id":"acomp-cor-coronary-variants-s04-03","region":"cor-coronary-variants","category":"coronary","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Cardioplegia implications","text":"{{c1::Retrograde cardioplegia}} can supplement protection but is less reliable for the RV and does not remove the need to understand coronary origin."},
  {"id":"acomp-val-aortic-root-geometry-s01-01","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Build the root from the bottom up","text":"The {{c1::virtual basal ring}} connects the nadirs of the three cusp insertions and is the practical annular plane used for sizing."},
  {"id":"acomp-val-aortic-root-geometry-s01-02","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Build the root from the bottom up","text":"Cusp attachments rise in a {{c1::crown shape}} to three commissures."},
  {"id":"acomp-val-aortic-root-geometry-s01-03","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Build the root from the bottom up","text":"Between this haemodynamic junction and the anatomic ventriculoarterial junction are muscular and fibrous triangles that explain why part of the {{c1::root}} is ventricular myocardium and part is fibrous continuity with the mitral valve."},
  {"id":"acomp-val-aortic-root-geometry-s02-01","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"What makes the valve competent","text":"Each cusp must have adequate {{c1::geometric height and effective height}}, meet its neighbours centrally, and coapt over a sufficient vertical length."},
  {"id":"acomp-val-aortic-root-geometry-s02-02","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"What makes the valve competent","text":"Root or {{c1::sinotubular-junction dilatation}} pulls commissures apart and can cause regurgitation despite normal cusps."},
  {"id":"acomp-val-aortic-root-geometry-s02-03","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"What makes the valve competent","text":"Conversely, a restricted, calcified, or {{c1::fenestrated cusp}} can fail within a normal-sized root."},
  {"id":"acomp-val-aortic-root-geometry-s03-01","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Coronary and conduction relations","text":"The left and {{c1::right coronary ostia}} arise from their respective sinuses, usually below the sinotubular junction."},
  {"id":"acomp-val-aortic-root-geometry-s03-02","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Coronary and conduction relations","text":"The {{c1::noncoronary sinus}} relates to the interatrial septum."},
  {"id":"acomp-val-aortic-root-geometry-s03-03","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Coronary and conduction relations","text":"The {{c1::membranous septum}} and penetrating His bundle lie beneath the right–noncoronary commissural region, making deep annular sutures there a cause of postoperative heart block."},
  {"id":"acomp-val-aortic-root-geometry-s04-01","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"How anatomy changes the operation","text":"Valve replacement requires {{c1::annular debridement}} without entering the aortic-mitral curtain, ventricular septum, or coronary ostia."},
  {"id":"acomp-val-aortic-root-geometry-s04-02","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"How anatomy changes the operation","text":"{{c1::Valve-sparing root}} replacement preserves the cusps but restores basal and sinotubular dimensions."},
  {"id":"acomp-val-aortic-root-geometry-s04-03","region":"val-aortic-root-geometry","category":"valves","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"How anatomy changes the operation","text":"Root replacement mobilizes the coronaries as buttons; inadequate mobilization, tension, twisting, or a low reimplantation site risks {{c1::coronary malperfusion}}."},
  {"id":"acomp-val-fibrous-skeleton-s01-01","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"The load-bearing frame","text":"The anterior mitral leaflet is continuous with the left and noncoronary aortic cusps through the {{c1::intervalvular fibrosa}}, also called the aorto-mitral curtain."},
  {"id":"acomp-val-fibrous-skeleton-s01-02","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"The load-bearing frame","text":"The {{c1::right and left fibrous trigones and the central fibrous body}} connect the aortic and mitral annuli."},
  {"id":"acomp-val-fibrous-skeleton-s01-03","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"The load-bearing frame","text":"This {{c1::curtain}} forms the roof of the LVOT and transmits force between the two valves."},
  {"id":"acomp-val-fibrous-skeleton-s02-01","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Electrical insulation and the one normal bridge","text":"{{c1::Fibrous tissue}} electrically separates atrial from ventricular myocardium."},
  {"id":"acomp-val-fibrous-skeleton-s02-02","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Electrical insulation and the one normal bridge","text":"The {{c1::AV node and penetrating bundle of His}} form the normal electrical connection through this barrier near the central fibrous body."},
  {"id":"acomp-val-fibrous-skeleton-s02-03","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Electrical insulation and the one normal bridge","text":"Accessory pathways are {{c1::abnormal muscular bridges}} around the annuli that bypass this insulation."},
  {"id":"acomp-val-fibrous-skeleton-s03-01","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Neighbouring danger zones","text":"The {{c1::left atrium}} lies behind the aorto-mitral curtain, the membranous septum and conduction axis lie near its right side, and the circumflex artery courses close to the posterior mitral annulus—especially near the anterolateral commissural region."},
  {"id":"acomp-val-fibrous-skeleton-s03-02","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Neighbouring danger zones","text":"Deep or {{c1::misplaced sutures}} can therefore create atrial perforation, heart block, or circumflex injury."},
  {"id":"acomp-val-fibrous-skeleton-s03-03","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Neighbouring danger zones","text":"The conduction axis and membranous septum lie near the {{c1::right side of the aorto-mitral curtain}}."},
  {"id":"acomp-val-fibrous-skeleton-s04-01","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"When the skeleton is destroyed","text":"{{c1::Endocarditis}} can produce an intervalvular fibrosa abscess, pseudoaneurysm, or aorto-atrial fistula."},
  {"id":"acomp-val-fibrous-skeleton-s04-02","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"When the skeleton is destroyed","text":"Reconstruction may require radical debridement and {{c1::patch rebuilding of the curtain}} before one or both valves can be implanted."},
  {"id":"acomp-val-fibrous-skeleton-s04-03","region":"val-fibrous-skeleton","category":"valves","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"When the skeleton is destroyed","text":"The anatomy determines whether a standard valve operation is possible or a {{c1::complex double-valve reconstruction}} is required."},
  {"id":"acomp-cond-operative-danger-zones-s01-01","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"The conduction axis in one continuous line","text":"The {{c1::SA node}} lies subepicardially at the superior cavoatrial junction."},
  {"id":"acomp-cond-operative-danger-zones-s01-02","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"The conduction axis in one continuous line","text":"Atrial activation reaches the compact AV node at the {{c1::apex}} of the triangle of Koch."},
  {"id":"acomp-cond-operative-danger-zones-s01-03","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"The conduction axis in one continuous line","text":"The penetrating His bundle crosses the central fibrous body, reaches the {{c1::membranous septum}}, and divides into right and left bundle branches along the ventricular septum."},
  {"id":"acomp-cond-operative-danger-zones-s02-01","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Aortic and root procedures","text":"The His bundle is closest to the {{c1::aortic annulus}} beneath the right–noncoronary commissural region."},
  {"id":"acomp-cond-operative-danger-zones-s02-02","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Aortic and root procedures","text":"Aggressive debridement, {{c1::deep sutures}}, an oversized prosthesis, septal haematoma, or local oedema can cause new bundle-branch block or complete AV block."},
  {"id":"acomp-cond-operative-danger-zones-s02-03","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Aortic and root procedures","text":"The risk is higher when {{c1::calcification}} extends into the membranous septum."},
  {"id":"acomp-cond-operative-danger-zones-s03-01","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Mitral and tricuspid procedures","text":"At the {{c1::tricuspid valve}}, protect the apex of the triangle of Koch and the anteroseptal commissural region; annuloplasty bites along the septal annulus should be shallow and anatomically deliberate."},
  {"id":"acomp-cond-operative-danger-zones-s03-02","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Mitral and tricuspid procedures","text":"At the {{c1::mitral valve}}, the conduction axis is less immediately adjacent, but sutures near the right fibrous trigone and central fibrous body can still injure it."},
  {"id":"acomp-cond-operative-danger-zones-s03-03","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Mitral and tricuspid procedures","text":"Tricuspid annuloplasty bites along the {{c1::septal annulus}} should remain shallow and anatomically deliberate."},
  {"id":"acomp-cond-operative-danger-zones-s04-01","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Septal and congenital procedures","text":"Perimembranous VSD closure is dangerous because the conduction bundle runs along the {{c1::posteroinferior rim}} of the defect."},
  {"id":"acomp-cond-operative-danger-zones-s04-02","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Septal and congenital procedures","text":"The precise relation varies with defect anatomy, so the surgeon places sutures on the right-ventricular side with awareness that a {{c1::normal-looking rim}} may contain the bundle."},
  {"id":"acomp-cond-operative-danger-zones-s04-03","region":"cond-operative-danger-zones","category":"conduction","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Septal and congenital procedures","text":"New {{c1::complete heart block}} after valve or septal surgery is often an anatomic injury, compression, or oedema at one of these predictable sites."},
  {"id":"acomp-ves-ascending-arch-s01-01","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Root, ascending aorta and arch","text":"The {{c1::root}} extends from the virtual basal ring to the sinotubular junction."},
  {"id":"acomp-ves-ascending-arch-s01-02","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Root, ascending aorta and arch","text":"The {{c1::tubular ascending aorta}} continues to the origin of the brachiocephalic artery."},
  {"id":"acomp-ves-ascending-arch-s01-03","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Root, ascending aorta and arch","text":"The {{c1::arch}} curves posteriorly and leftward over the left main bronchus and becomes descending aorta near the ligamentum arteriosum."},
  {"id":"acomp-ves-ascending-arch-s02-01","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Arch branches and common variants","text":"The usual order is brachiocephalic, left common carotid, and {{c1::left subclavian artery}}."},
  {"id":"acomp-ves-ascending-arch-s02-02","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Arch branches and common variants","text":"A common origin of the brachiocephalic and {{c1::left common carotid arteries}} is frequent."},
  {"id":"acomp-ves-ascending-arch-s02-03","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Arch branches and common variants","text":"A {{c1::separate left vertebral artery}} may arise between the left common carotid and left subclavian."},
  {"id":"acomp-ves-ascending-arch-s03-01","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Structures crossing the field","text":"The {{c1::left brachiocephalic vein}} crosses anterior to the arch branches."},
  {"id":"acomp-ves-ascending-arch-s03-02","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Structures crossing the field","text":"The {{c1::right pulmonary artery}} lies behind the ascending aorta."},
  {"id":"acomp-ves-ascending-arch-s03-03","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Structures crossing the field","text":"The {{c1::left recurrent laryngeal nerve}} loops beneath the arch beside the ligamentum arteriosum; injury causes left vocal-cord paralysis."},
  {"id":"acomp-ves-ascending-arch-s04-01","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Cerebral perfusion anatomy","text":"Right axillary or {{c1::innominate cannulation}} directs antegrade flow into the right carotid and right vertebral systems."},
  {"id":"acomp-ves-ascending-arch-s04-02","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Cerebral perfusion anatomy","text":"Whether unilateral perfusion protects the left hemisphere depends on the {{c1::circle of Willis}} and collateral pathways."},
  {"id":"acomp-ves-ascending-arch-s04-03","region":"ves-ascending-arch","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Cerebral perfusion anatomy","text":"{{c1::Bilateral selective perfusion}} adds a left-carotid cannula when anatomy or monitoring suggests inadequate cross-filling."},
  {"id":"acomp-ves-pulmonary-s01-01","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Pulmonary trunk and bifurcation","text":"The pulmonary trunk arises from the RVOT, lies left and initially anterior to the {{c1::ascending aorta}}, and bifurcates beneath the concavity of the arch."},
  {"id":"acomp-ves-pulmonary-s01-02","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Pulmonary trunk and bifurcation","text":"The {{c1::right pulmonary artery}} passes horizontally behind the ascending aorta and SVC and in front of the right main bronchus."},
  {"id":"acomp-ves-pulmonary-s01-03","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Pulmonary trunk and bifurcation","text":"The {{c1::left pulmonary artery}} passes over the left main bronchus and connects to the arch through the ligamentum arteriosum."},
  {"id":"acomp-ves-pulmonary-s02-01","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"The hilar map","text":"At the right hilum the pulmonary artery is generally {{c1::anterior to the bronchus}}; at the left hilum it is superior to the bronchus—remember RALS: Right Anterior, Left Superior."},
  {"id":"acomp-ves-pulmonary-s02-02","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"The hilar map","text":"Pulmonary veins lie anterior and inferior at both hila and have {{c1::thinner walls}} than the arteries."},
  {"id":"acomp-ves-pulmonary-s02-03","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"The hilar map","text":"At the left hilum, the pulmonary artery lies {{c1::superior to the bronchus}}."},
  {"id":"acomp-ves-pulmonary-s03-01","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Pulmonary veins and left atrium","text":"{{c1::Four pulmonary veins}} usually enter the posterior LA, with right and left superior and inferior veins."},
  {"id":"acomp-ves-pulmonary-s03-02","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Pulmonary veins and left atrium","text":"Variants include a common left venous trunk and {{c1::additional right middle-lobe veins}}."},
  {"id":"acomp-ves-pulmonary-s03-03","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Pulmonary veins and left atrium","text":"The veins form the lateral boundaries of the {{c1::oblique pericardial sinus}} and are the key landmarks for left-atrial ablation and transplant anastomoses."},
  {"id":"acomp-ves-pulmonary-s04-01","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Operative hazards","text":"Dissection behind the {{c1::ascending aorta}} can injure the right pulmonary artery."},
  {"id":"acomp-ves-pulmonary-s04-02","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Operative hazards","text":"A clamp or suture at the ligamentum region can injure the {{c1::left recurrent laryngeal nerve}}."},
  {"id":"acomp-ves-pulmonary-s04-03","region":"ves-pulmonary","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Operative hazards","text":"{{c1::Pulmonary-vein cannulation}} or ablation too deep can create stenosis; too proximal an ablation line may leave arrhythmogenic venous myocardium connected."},
  {"id":"acomp-ves-caval-cannulation-s01-01","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Caval entry into the right atrium","text":"The {{c1::SVC}} enters the superior right atrium without a valve."},
  {"id":"acomp-ves-caval-cannulation-s01-02","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Caval entry into the right atrium","text":"The {{c1::IVC}} enters inferiorly and is partly guarded by the Eustachian valve."},
  {"id":"acomp-ves-caval-cannulation-s01-03","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:01","sourceKind":"section","sourceIndex":0,"sourceTitle":"Caval entry into the right atrium","text":"The {{c1::coronary sinus}} enters posteroinferiorly near the septal tricuspid annulus and may have a Thebesian valve."},
  {"id":"acomp-ves-caval-cannulation-s02-01","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Two-stage versus bicaval cannulation","text":"A {{c1::two-stage cannula}} placed through the right atrial appendage drains the IVC through its distal basket and the RA/SVC through a proximal stage; it is efficient when the right heart stays closed."},
  {"id":"acomp-ves-caval-cannulation-s02-02","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Two-stage versus bicaval cannulation","text":"Separate SVC and IVC cannulas with caval tapes provide {{c1::bicaval isolation}} for tricuspid, atrial septal, congenital, and many mitral procedures."},
  {"id":"acomp-ves-caval-cannulation-s02-03","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:02","sourceKind":"section","sourceIndex":1,"sourceTitle":"Two-stage versus bicaval cannulation","text":"When the right heart remains closed, the two-stage cannula is placed through the {{c1::right atrial appendage}}."},
  {"id":"acomp-ves-caval-cannulation-s03-01","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Where injury occurs","text":"High SVC dissection risks the {{c1::right phrenic nerve}} and SA-node artery near the cavoatrial junction."},
  {"id":"acomp-ves-caval-cannulation-s03-02","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Where injury occurs","text":"Deep IVC cannulation can enter a {{c1::hepatic vein}}; a poorly positioned cannula can obstruct venous return or crowd the atrial septum."},
  {"id":"acomp-ves-caval-cannulation-s03-03","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:03","sourceKind":"section","sourceIndex":2,"sourceTitle":"Where injury occurs","text":"Purse-string bites that are too deep can tear {{c1::fragile atrial tissue}} when the cannula is secured."},
  {"id":"acomp-ves-caval-cannulation-s04-01","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Femoral venous route","text":"A {{c1::femoral venous cannula}} passes through the external and common iliac veins into the IVC and ideally reaches the SVC under transoesophageal echocardiographic or fluoroscopic guidance."},
  {"id":"acomp-ves-caval-cannulation-s04-02","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Femoral venous route","text":"Iliocaval tortuosity, {{c1::thrombus}}, filters, and congenital interruption can prevent safe passage."},
  {"id":"acomp-ves-caval-cannulation-s04-03","region":"ves-caval-cannulation","category":"vessels","subtype":"surgical","partId":"section:04","sourceKind":"section","sourceIndex":3,"sourceTitle":"Femoral venous route","text":"{{c1::Vacuum assistance}} improves drainage but magnifies the consequences of malposition or air entrainment."}
);
